method below_zero(operations: seq<int>) returns (result: bool)
    requires operations != null
    ensures result == (exists i :: 0 <= i < |operations| && (|operations[0..i]| + operations[i] < 0))
{
    var balance := 0;
    result := false;

    // Iterate through each operation in the list
    var i := 0;
    while i < |operations|
        invariant 0 <= i <= |operations|
        invariant balance == (if i == 0 then 0 else |operations[0..i-1]|)
    {
        balance := balance + operations[i];

        // Check if the balance falls below zero
        if balance < 0 {
            result := true;
            break;
        }

        i := i + 1;
    }
}
```

